// app/(auth)/layout.jsx
import { Inter } from 'next/font/google';
import { Toaster } from 'sonner'; // Changed from Sonner to Toaster
import { ThemeProvider } from '@/components/theme-provider';
import AuthBackground from '@/components/auth/AuthBackground';
import { cn } from '@/lib/utils';

const inter = Inter({ subsets: ['latin'] });

export default function AuthLayout({ children }) {
  return (
    <html lang="en" suppressHydrationWarning>
      <body className={cn(
        "min-h-screen bg-background antialiased",
        inter.className
      )}>
        <ThemeProvider
          attribute="class"
          defaultTheme="system"
          enableSystem
          disableTransitionOnChange
        >
          {/* Background with decorative elements */}
          <AuthBackground />
          
          {/* Main content container */}
          <main className="relative z-10 flex items-center justify-center min-h-screen p-4">
            <div className="w-full max-w-md">
              {/* Branding */}
              <div className="mb-8 text-center">
                <div className="flex justify-center mb-4">
                  <div className="bg-muted border rounded-full w-16 h-16 flex items-center justify-center">
                    <svg xmlns="http://www.w3.org/2000/svg" 
                         viewBox="0 0 24 24" 
                         fill="none" 
                         stroke="currentColor" 
                         strokeWidth="2" 
                         className="w-8 h-8 text-primary">
                      <path d="M15 6v12a3 3 0 1 0 3-3H6a3 3 0 1 0 3 3V6a3 3 0 1 0-3 3h12a3 3 0 1 0-3-3" />
                    </svg>
                  </div>
                </div>
                <h1 className="text-3xl font-bold tracking-tight">Your SaaS Name</h1>
                <p className="text-muted-foreground mt-2">Sign in to your account</p>
              </div>
              
              {/* Authentication card */}
              <div className="bg-background border rounded-xl shadow-lg p-6 sm:p-8">
                {children}
              </div>
              
              {/* Footer links */}
              <div className="mt-8 text-center text-sm text-muted-foreground">
                <p>© {new Date().getFullYear()} Your Company. All rights reserved.</p>
                <div className="flex justify-center space-x-4 mt-2">
                  <a href="#" className="hover:text-primary hover:underline">Terms</a>
                  <a href="#" className="hover:text-primary hover:underline">Privacy</a>
                  <a href="#" className="hover:text-primary hover:underline">Support</a>
                </div>
              </div>
            </div>
          </main>
          
          {/* Toast notifications - Updated to use Toaster */}
          <Toaster position="top-center" richColors />
        </ThemeProvider>
      </body>
    </html>
  );
}